                        if (caption.Width < preferredWidth || caption.Bottom > caption.Parent.ClientSize.Height + 1) throw new InvalidOperationException("Summary metric caption is clipped at " + scale.ToString("0.0") + " scale: " + caption.Text + ".");
                    }
